import test from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { requestHash } from "@oma/domain/request-identity";
import { canonicalJson } from "@oma/domain/canonical-json";
import {
  buildRequestIdentity, canonicalRequestParams, requestParamsEqual, firstRequestProjectionMismatch,
} from "@oma/domain/request-identity";

// Literal pre-refactor hash-domain bytes, not outputs generated by the new helper.
// Digests are computed independently when tests run; no execution is claimed here.
const legacyVectors: ReadonlyArray<readonly [string, unknown, string]> = [
  ["mail.send", { to: ["bob", "alice", "bob"], body: " body\n", subject: " subject ", kind: "message" },
    '{"method":"mail.send","params":{"body":" body\\n","kind":"message","subject":" subject ","to":["alice","bob"]}}'],
  ["mail.ack", { message: "message-id" }, '{"method":"mail.ack","params":{"message":"message-id"}}'],
  ["route.follow", { topic: "work" }, '{"method":"route.follow","params":{"topic":"work"}}'],
  ["route.unfollow", { topic: "work" }, '{"method":"route.unfollow","params":{"topic":"work"}}'],
  ["agent.create", { name: "alice", from: "candidate", brief: "brief" },
    '{"method":"agent.create","params":{"brief":"brief","from":"candidate","name":"alice"}}'],
  ["agent.start", { agent: "alice" }, '{"method":"agent.start","params":{"agent":"alice"}}'],
  ["agent.stop", { agent: "alice" }, '{"method":"agent.stop","params":{"agent":"alice"}}'],
  ["agent.continue", { note: "note" }, '{"method":"agent.continue","params":{"note":"note"}}'],
  ["git.submit", {
    candidate: "candidate", exportRef: "refs/oma/export/example", prerequisites: ["b", "a", "a"],
    to: ["bob", "alice", "bob"], paths: ["z", "a", "z"], subject: "subject", body: "body",
    bundle: { bytes: 1, sha256: "digest", mediaType: "application/x-git-bundle" },
  }, '{"method":"git.submit","params":{"body":"body","bundle":{"bytes":1,"mediaType":"application/x-git-bundle","sha256":"digest"},"candidate":"candidate","exportRef":"refs/oma/export/example","paths":["a","z"],"prerequisites":["a","b"],"subject":"subject","to":["alice","bob"]}}'],
  ["git.integrate", { candidate: "candidate", expected: "base" },
    '{"method":"git.integrate","params":{"candidate":"candidate","expected":"base"}}'],
  ["context.publish", {
    expected: null, entries: [{ path: "GOAL.md", bytes: 1, sha256: "digest" }],
    content: { bytes: 1, sha256: "digest", mediaType: "application/vnd.oma.context-v1" },
  }, '{"method":"context.publish","params":{"content":{"bytes":1,"mediaType":"application/vnd.oma.context-v1","sha256":"digest"},"entries":[{"bytes":1,"path":"GOAL.md","sha256":"digest"}],"expected":null}}'],
];

test("all mutation hash domains retain their literal legacy canonical bytes", () => {
  for (const [method, params, bytes] of legacyVectors) {
    const identity = buildRequestIdentity(method, params);
    assert.equal(Buffer.from(identity.canonicalBytes).toString("utf8"), bytes, method);
    const legacyHash = createHash("sha256").update(bytes, "utf8").digest("hex");
    assert.equal(identity.hash, legacyHash, method);
    assert.equal(requestHash(method, params), legacyHash, method);
    assert.equal(requestHash(method, canonicalRequestParams(method, params)), legacyHash, method);
  }
});

test("only the established request string sets are order/duplicate insensitive", () => {
  assert.equal(requestHash("mail.send", { to: ["b", "a", "a"] }), requestHash("mail.send", { to: ["a", "b"] }));
  assert.equal(requestHash("git.submit", { to: ["b", "a"], prerequisites: ["b", "a", "b"], paths: ["z", "a"] }),
    requestHash("git.submit", { paths: ["a", "z", "z"], prerequisites: ["a", "b"], to: ["a", "b", "b"] }));
  for (const [method, field] of [["mail.send", "refs"], ["context.publish", "entries"], ["other", "argv"]]) {
    assert.notEqual(requestHash(method!, { [field!]: ["a", "b"] }), requestHash(method!, { [field!]: ["b", "a"] }));
  }
  for (const field of ["body", "subject", "candidate", "expected"]) {
    assert.notEqual(requestHash("git.submit", { [field]: "a" }), requestHash("git.submit", { [field]: "b" }));
  }
  assert.notEqual(requestHash("route.follow", { topic: "work" }), requestHash("route.unfollow", { topic: "work" }));
  assert.notEqual(requestHash("mail.send", { body: "é" }), requestHash("mail.send", { body: "e\u0301" }));
  assert.notEqual(requestHash("mail.send", { body: "body" }), requestHash("mail.send", { body: "body\n" }));
});

test("DR46: separate stream identity is refused; current descriptors remain in params", () => {
  // @ts-expect-error The old third parameter is intentionally outside the current API.
  assert.throws(() => buildRequestIdentity("git.submit", { value: 1 }, { bytes: 2, sha256: "digest" }), TypeError);
  // @ts-expect-error The mutation hash rejects the same removed argument.
  assert.throws(() => requestHash("git.submit", { value: 1 }, { bytes: 2, sha256: "digest" }), TypeError);
  for (const [method, params] of legacyVectors) {
    assert.equal(Object.hasOwn(JSON.parse(Buffer.from(buildRequestIdentity(method, params).canonicalBytes).toString("utf8")), "stream"), false);
  }
  assert.notEqual(requestHash("git.submit", { bundle: { bytes: 2, sha256: "a" } }),
    requestHash("git.submit", { bundle: { bytes: 2, sha256: "b" } }));
});

test("CLI projections share field semantics but never rewrite a frozen cache", () => {
  const frozen = Object.freeze({ to: Object.freeze(["bob", "alice", "bob"]), subject: " subject ", body: "frozen body" });
  const before = JSON.stringify(frozen);
  assert.equal(firstRequestProjectionMismatch("mail.send", { to: ["alice", "bob"] }, frozen), null);
  assert.equal(firstRequestProjectionMismatch("mail.send", { subject: "subject" }, frozen), "subject");
  assert.equal(firstRequestProjectionMismatch("mail.send", { missing: null }, frozen), "missing");
  assert.equal(firstRequestProjectionMismatch("context.publish", { entries: ["a", "b"] }, { entries: ["b", "a"] }), "entries");
  assert.equal(requestParamsEqual("mail.send", { body: "same", to: ["a", "a"] }, { to: ["a"], body: "same" }), true);
  assert.equal(JSON.stringify(frozen), before);
});

test("JSON casts, accessors, cycles and non-JSON values cannot bypass identity validation", () => {
  let getterCalled = false;
  const getter = { get body() { getterCalled = true; return "body"; } };
  assert.throws(() => buildRequestIdentity("mail.send", getter), /accessors/);
  assert.equal(getterCalled, false);
  const cycle: Record<string, unknown> = {};
  cycle.self = cycle;
  for (const invalid of [undefined, NaN, Infinity, 1n, () => 1, new Date(), cycle, { body: undefined }, [, 1]])
    assert.throws(() => buildRequestIdentity("mail.send", invalid));
  assert.throws(() => buildRequestIdentity("mail.send", { to: ["alice", 1] }), /string set/);
  const proto = JSON.parse('{"__proto__":{"polluted":true},"a":1}');
  assert.equal(canonicalJson(proto), '{"__proto__":{"polluted":true},"a":1}');
  assert.equal(Object.hasOwn({}, "polluted"), false);
});
